function ensureTeamMetadata(){
 if(!state || typeof state!=='object')return;
 if(!state.workspace || typeof state.workspace!=='object' || Array.isArray(state.workspace))state.workspace={};
 // Never change identifiers once stored, including if the app changes its display name.
 if(typeof state.workspace.organizationId!=='string'||!state.workspace.organizationId)state.workspace.organizationId=DEMO_ORGANIZATION_ID;
 if(typeof state.workspace.teamId!=='string'||!state.workspace.teamId)state.workspace.teamId=DEMO_TEAM_ID;
 if(typeof state.workspace.teamName!=='string')state.workspace.teamName='Kyutech鹿児島（試作）';
 if(!Number.isInteger(state.dataSchemaVersion) || state.dataSchemaVersion<DATA_SCHEMA_VERSION)state.dataSchemaVersion=DATA_SCHEMA_VERSION;
 const teamId=state.workspace.teamId;
 // Existing IDs remain stable. Missing teamId is filled only for this single-team prototype.
 for(const group of ['players','records','goals','trainingTypes','metrics','coaches','trainingAssignments','reflections','parentReflections','parentMessages','activities','demoUsers']){
  if(!Array.isArray(state[group]))continue;
  for(const item of state[group]){
   if(item && typeof item==='object' && !Array.isArray(item) && !item.teamId)item.teamId=teamId;
  }
 }
 // Additional state maps (longGoals, shortGoals, goalTargets) remain player-ID keyed legacy
 // structures. They must be converted to team-scoped tables before multi-team hosting.
}

