function esc(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function id(){return (crypto.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2))}
function today(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function db(){if(!dbPromise)dbPromise=new Promise((res,rej)=>{const r=indexedDB.open(STORAGE,1);r.onupgradeneeded=()=>r.result.createObjectStore('app');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});return dbPromise}
async function readState(){const d=await db();return new Promise((res,rej)=>{const t=d.transaction('app','readonly');const r=t.objectStore('app').get('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function writeState(){ensureTeamMetadata();const d=await db();return new Promise((res,rej)=>{const t=d.transaction('app','readwrite');t.objectStore('app').put(state,'state');t.oncomplete=()=>res();t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)})}
async function persist(msg='保存しました'){try{await writeState();message(msg);return true}catch(e){message('保存に失敗しました。記録を控え、容量を確認してください。',true);return false}}
function message(msg,err=false){notice=msg;noticeError=err;const el=$('notice');if(el){el.className='feedback'+(err?' error':'');el.textContent=msg}}
function btn(action,label,klass='btn small',extra=''){return `<button type="button" class="${klass}" data-action="${esc(action)}" ${extra}>${esc(label)}</button>`}
function f(label,key,value='',opts={}){const name=opts.name||key;return `<div class="field"><label for="${esc(name)}">${esc(label)}${opts.unit?'（'+esc(opts.unit)+'）':''}</label><input id="${esc(name)}" name="${esc(name)}" type="${opts.type||'text'}" ${opts.type==='number'?'inputmode="decimal" step="any"':''} value="${esc(value)}" ${opts.required?'required':''} ${opts.min!==undefined?'min="'+opts.min+'"':''} placeholder="${esc(opts.placeholder||'')}">${opts.hint?'<small>'+esc(opts.hint)+'</small>':''}</div>`}
function select(name,label,values,current){return `<div class="field"><label for="${esc(name)}">${esc(label)}</label><select id="${esc(name)}" name="${esc(name)}">${values.map(v=>`<option value="${esc(v.value)}" ${String(v.value)===String(current)?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div>`}
function visibleRec(){return state.records.filter(r=>r.playerId===selected).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt))}
function prev(kind,match){return visibleRec().find(r=>r.kind===kind&&(!match||match(r)))}
function prettyType(t){return {baseball:'野球成績',training:'トレーニング',inbody:'InBody',ability:'パフォーマンス測定'}[t]||t}
function prettyRecord(r){if(r.kind==='baseball')return `${r.opponent||'対戦相手未入力'}・${{batting:'打撃',pitching:'投手',fielding:'守備',running:'走塁'}[r.category]||''}`;if(r.kind==='training')return `${r.activityName}・${['weight','reps','sets','time','distance'].filter(k=>r.values?.[k]!==''&&r.values?.[k]!==undefined).map(k=>r.values[k]+({weight:'kg',reps:'回',sets:'セット',time:'分',distance:'m'}[k])).join(' / ')}${r.specificRecord?' / '+r.specificRecord:''}${r.personalBest?' ★自己ベスト':''}`;if(r.kind==='inbody')return `体重 ${r.values.weight??'—'}kg / 骨格筋量 ${r.values.muscle??'—'}kg`;if(r.kind==='ability')return `${Object.keys(r.values).length}項目を測定`;return ''}
const METRIC_STANDARD=[['スイングスピード','km/h','high'],['打球速度','km/h','high'],['送球速度','km/h','high'],['遠投','m','high'],['10m走','秒','low'],['30m走','秒','low'],['50m走','秒','low'],['握力','kg','high'],['立ち幅跳び','cm','high'],['垂直跳び','cm','high']];
function normalizeState(){
 ensureTeamMetadata();
 state.activities=Array.isArray(state.activities)?state.activities:[];
 if(!Array.isArray(state.demoUsers))state.demoUsers=clone(DEMO_USERS);
 for(const def of DEMO_USERS){if(!state.demoUsers.some(x=>x.id===def.id))state.demoUsers.push(clone(def));}
 for(const u of state.demoUsers){if(u.role==='staff'&&!Array.isArray(u.assignedPlayerIds))u.assignedPlayerIds=[];}

 state.coaches=Array.isArray(state.coaches)?state.coaches:[{id:'coach-a',name:'スタッフA'},{id:'coach-b',name:'スタッフB'},{id:'coach-c',name:'スタッフC'}];
 state.trainingAssignments=Array.isArray(state.trainingAssignments)?state.trainingAssignments:[];
 state.reflections=Array.isArray(state.reflections)?state.reflections:[];
 state.longGoals=state.longGoals&&typeof state.longGoals==='object'&&!Array.isArray(state.longGoals)?state.longGoals:{};
 state.shortGoals=state.shortGoals&&typeof state.shortGoals==='object'&&!Array.isArray(state.shortGoals)?state.shortGoals:{};
 state.parentReflections=Array.isArray(state.parentReflections)?state.parentReflections:[];
 state.parentMessages=Array.isArray(state.parentMessages)?state.parentMessages:[];
 state.playerPlans=state.playerPlans&&typeof state.playerPlans==='object'?state.playerPlans:{};
 state.coachFeedback=Array.isArray(state.coachFeedback)?state.coachFeedback:[];
 // デモ用の割当は架空の選手だけに初回登録。実在選手の履歴は推定しない。
 if(!state.sampleAssignmentsV08){const t=state.trainingTypes[0];if(t){for(const pl of state.players){const match=/^test([1-9]|1\d|2[0-5])$/.exec(pl.name);if(!match||pl.grade!=='テスト')continue;const n=Number(match[1]);state.trainingAssignments.push({id:'demo-v08-'+pl.id,playerId:pl.id,coachId:state.coaches[(n-1)%state.coaches.length].id,activityId:state.trainingTypes[(n-1)%state.trainingTypes.length].id,description:'週2回・フォームを意識して実施（架空の指示）',assignedAt:'2026-11-15',demo:true});}}state.sampleAssignmentsV08=true;}
 state.goalTargets=state.goalTargets&&typeof state.goalTargets==='object'&&!Array.isArray(state.goalTargets)?state.goalTargets:{};
 state.readActivity=state.readActivity&&typeof state.readActivity==='object'?state.readActivity:{};
 state.readActivityParent=state.readActivityParent&&typeof state.readActivityParent==='object'?state.readActivityParent:{};
 for(const p of state.players){if(typeof p.parentName!=='string')p.parentName='未登録';if(/^tet([1-9]|1\d|2[0-5])$/.test(p.name))p.name=p.name.replace(/^tet/,'test');if(/^tet([1-9]|1\d|2[0-5])の家庭$/.test(p.parentName))p.parentName=p.parentName.replace(/^tet/,'test');}
 for(const [name,unit,better] of METRIC_STANDARD){if(!state.metrics.some(m=>m.name===name||name==='スイングスピード'&&m.name==='スイング速度'))state.metrics.push({id:id(),name,unit,better});}
 const oldSwing=state.metrics.find(m=>m.name==='スイング速度');if(oldSwing)oldSwing.name='スイングスピード';
}
// v0.6: fictitious records for the test players only; inserted once on first launch.
// Never overwrite a player who already has records. Do not create fake unread notifications.
function addSampleRecordsOnce(){
 if(state.sampleDataV06)return 0;
 const dates=['2026-04-12','2026-07-24','2026-11-15'];
 const when='2026-11-20T00:00:00.000Z';
 const metricByName=new Map(state.metrics.map(m=>[m.name,m]));
 let added=0;
 for(const p of state.players){
  const hit=/^test([1-9]|1\d|2[0-5])$/.exec(p.name);
  if(!hit||p.grade!=='テスト'||state.records.some(r=>r.playerId===p.id))continue;
  const n=Number(hit[1]);
  const variation=(n-1)%6;
  const records=[];
  const goal={};
  for(let i=0;i<3;i++){
   const date=dates[i];
   const prefix='demo-v06-'+p.id+'-'+i;
   const createdAt=when;
   const batting={pa:4,ab:3,hits:[0,1,2][i]+(n%5===0?1:0),doubles:i===2?1:0,triples:0,hr:0,rbi:i,walks:1,hbp:0,strikeouts:[2,1,0][i],sacflies:0,sacbunts:0};
   records.push({id:prefix+'-baseball',playerId:p.id,kind:'baseball',date,createdAt,updatedAt:createdAt,category:'batting',opponent:['サンプルA中','サンプルB中','サンプルC中'][i],tournament:'練習試合（架空）',gameType:'練習試合',values:batting,comment:'架空の入力例：打撃成績'});
   records.push({id:prefix+'-training',playerId:p.id,kind:'training',date,createdAt,updatedAt:createdAt,activityId:'t1',activityName:'スクワット',values:{weight:20+variation*2+i*5,reps:8+i,sets:3},specificRecord:'フォーム確認',personalBest:i===2,coachComment:'架空データ：姿勢を意識しよう',comment:'サンプル記録'});
   const weight=43+variation*.8+i*1.2;
   records.push({id:prefix+'-inbody',playerId:p.id,kind:'inbody',date,createdAt,updatedAt:createdAt,values:{height:151+variation*1.6+i*1.4,weight:Number(weight.toFixed(1)),muscle:Number((20+variation*.6+i*.8).toFixed(1)),fatMass:Number((9+variation*.3+i*.1).toFixed(1)),fatRate:Number((19+variation*.35-i*.4).toFixed(1)),lean:Number((weight-(9+variation*.3+i*.1)).toFixed(1)),water:Number((28+variation*.5+i*.6).toFixed(1)),leftArm:Number((1.55+variation*.04+i*.06).toFixed(2)),rightArm:Number((1.6+variation*.04+i*.06).toFixed(2)),trunk:Number((15+variation*.25+i*.35).toFixed(2)),rightLeg:Number((6.25+variation*.12+i*.2).toFixed(2)),leftLeg:Number((6.2+variation*.12+i*.2).toFixed(2))},photoData:null,comment:'架空のInBody値（実際の測定ではありません）'});
   const base={'スイングスピード':96+variation*2+i*7,'打球速度':105+variation*2+i*6,'送球速度':85+variation*2+i*5,'遠投':48+variation*2+i*7,'10m走':Number((2.1+variation*.03-i*.08).toFixed(2)),'30m走':Number((5.1+variation*.06-i*.15).toFixed(2)),'50m走':Number((8.1+variation*.08-i*.2).toFixed(2)),'握力':27+variation+i*3,'立ち幅跳び':182+variation*3+i*9,'垂直跳び':38+variation+i*3};
   const values={};for(const [name,value] of Object.entries(base)){const metric=metricByName.get(name);if(metric)values[metric.id]=value;}
   records.push({id:prefix+'-ability',playerId:p.id,kind:'ability',date,createdAt,updatedAt:createdAt,values,comment:'架空のパフォーマンス測定値'});
  }
  state.records.push(...records);added+=records.length;
  goal['training|t1:weight']=40+variation*2;
  goal['training|t1:reps']=12;
  goal['inbody|muscle']=24+variation*.6;
  goal['inbody|weight']=48+variation*.8;
  const goals={'スイングスピード':130+variation*2,'打球速度':140+variation*2,'送球速度':110+variation*2,'遠投':85+variation*2,'10m走':1.8+variation*.03,'30m走':4.3+variation*.06,'50m走':7.0+variation*.08,'握力':42+variation,'立ち幅跳び':235+variation*3,'垂直跳び':50+variation};
  for(const [name,value] of Object.entries(goals)){const metric=metricByName.get(name);if(metric)goal['ability|'+metric.id]=Number(value.toFixed(2));}
  goal['baseball|batting:hits']=3;
  state.goalTargets[p.id]={...goal,...(state.goalTargets[p.id]||{})};
 }
 state.sampleDataV06=true;
 return added;
}

