function compactNumber(label,key,unit,val,placeholder='—'){return `<div class="mini-field"><label for="${esc(key)}">${esc(label)} <span>${esc(unit)}</span></label><input type="number" id="${esc(key)}" name="${esc(key)}" inputmode="decimal" min="0" step="any" placeholder="${esc(placeholder)}" value="${esc(val??'')}"></div>`}
async function compressPhoto(file){
 if(!file)return null;
 if(!file.type.startsWith('image/'))throw Error('画像ファイルを選んでください');
 if(file.size>12*1024*1024)throw Error('元画像は12MB以下を選んでください');
 return await new Promise((resolve,reject)=>{const img=new Image();const src=URL.createObjectURL(file);img.onload=()=>{try{const scale=Math.min(1,1200/Math.max(img.width,img.height));const can=document.createElement('canvas');can.width=Math.max(1,Math.round(img.width*scale));can.height=Math.max(1,Math.round(img.height*scale));can.getContext('2d').drawImage(img,0,0,can.width,can.height);const data=can.toDataURL('image/jpeg',.68);URL.revokeObjectURL(src);if(data.length>1.8*1024*1024)throw Error('画像が大きすぎます。小さな写真で再試行してください');resolve(data)}catch(e){reject(e)}};img.onerror=()=>{URL.revokeObjectURL(src);reject(Error('画像を開けませんでした。JPEG/PNGをお試しください'))};img.src=src});
}

