function renderAccountManagement(){
 const selectPlayer=(u)=>`<select name="playerId" aria-label="対象選手">${state.players.map(p=>`<option value="${esc(p.id)}" ${p.id===u.playerId?'selected':''}>${esc(p.name)}（${esc(p.id)}）</option>`).join('')}</select>`;
 const list=state.demoUsers.filter(u=>DEMO_PASSWORDS[u.id]);
 return `<div class="page-head"><h2>アカウント管理・IDの紐づけ</h2></div><section class="card stack"><p class="help">4件のデモアカウントと対象選手・担当スタッフの対応を設定します。ログインIDと役割はテスト版では固定です。変更内容はこのブラウザ内に保存されます。</p><div class="account-list">${list.map(u=>`<form class="account-entry stack" data-user-id="${esc(u.id)}"><div class="row spaced"><div><b>${esc(u.name)}</b> <span class="pill">${esc(ROLE_NAMES[u.role])}</span></div><code>${esc(u.id)}</code></div>${u.role==='player'||u.role==='parent'?`<div class="field"><label>紐づく選手ID</label>${selectPlayer(u)}</div>`:u.role==='staff'?`<div class="field"><label>紐づくスタッフID</label><select name="coachId">${state.coaches.map(c=>`<option value="${esc(c.id)}" ${u.coachId===c.id?'selected':''}>${esc(c.name)}（${esc(c.id)}）</option>`).join('')}</select></div><div><label>担当選手（複数選択可能）</label><div class="account-player-grid">${state.players.map(p=>`<label class="account-check"><input type="checkbox" name="assignedPlayers" value="${esc(p.id)}" ${(u.assignedPlayerIds||[]).includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div></div>`:'<p class="note">監督アカウントはチーム全体を閲覧する画面です。</p>'}${u.role!=='admin'?`<div class="row">${btn('save-account:'+u.id,'紐づけを保存','btn primary')}</div>`:''}</form>`).join('')}</div></section><p class="note">※ この画面で設定するのは表示用の紐づけです。ブラウザ内のデータを他人から守る権限設定ではありません。本番にはサーバー側で本人確認・アクセス制御を行う仕組みが必要です。</p>`;
}

