function navIcon(name){return `<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON_PATHS[name]||ICON_PATHS.house}</svg>`;}
function pageIntro(title,desc){return `<div class="page-head growth-page-heading"><div><h2>${esc(title)}</h2>${desc?`<p class="subcopy">${esc(desc)}</p>`:''}</div></div>`;}
