function renderStaffPractice(){return `${pageIntro('練習設定','スタッフが主体的にトレーニングを提案・管理')}${renderCoachAssignmentEditor()}<section class="card stack" style="margin-top:14px"><h3 class="section-title">種目の管理と追加</h3><form id="training-add" class="row" style="align-items:end">${f('種目名','trainingName','',{required:true,placeholder:'例：シャドーピッチング'})}<div class="row"><label class="tiny"><input type="checkbox" name="fields" value="reps" checked>回数</label><label class="tiny"><input type="checkbox" name="fields" value="weight">負荷</label><label class="tiny"><input type="checkbox" name="fields" value="sets" checked>セット数</label></div>${btn('add-training','種目を追加','btn primary')}</form><p class="note">種目の詳細資料・測定項目の設定はデータ管理画面から行えます。</p></section>`;}
