function renderDirectorAnalysis(){return `${pageIntro('分析','育成と試合の戦術を確認する')}<div class="mode-tabs"><button data-action="analysis-mode:growth" class="${analysisMode==='growth'?'on':''}">育成分析</button><button data-action="analysis-mode:strategy" class="${analysisMode==='strategy'?'on':''}">戦術分析</button></div>${analysisMode==='growth'?renderTeamDashboard():renderStrategyPlaceholder()}`;}
function renderStrategyPlaceholder(){const batting=state.records.filter(r=>r.kind==='baseball'&&r.category==='batting');const matches=new Set(batting.map(r=>r.opponent+'|'+r.date));return `<section class="card stack"><h3 class="section-title">戦術分析｜今後のデータ整備項目</h3><div class="summary-grid"><div class="summary-box"><b>${matches.size}</b><span>記録のある試合（参考）</span></div><div class="summary-box"><b>${batting.length}</b><span>打撃記録件数</span></div></div><p class="note">得点しやすい局面・失点しやすい局面の分析には、走者状況・アウトカウント・得失点・機会数の記録が必要です。現在の打撃成績だけから局面別の確率を推定しません。</p></section>`;}
function renderDirectorCoach(){return `${pageIntro('指導管理','どのスタッフが、どの選手に何を提案しているか')}${renderCoachManagement()}`;}
function renderDataCenter(){if(dataManagerMode==='input')type=dataManagerKind;return `${pageIntro('データ管理','野球成績・測定・InBodyの入力と入出力')}<div class="mode-tabs"><button class="${dataManagerKind==='baseball'?'on':''}" data-action="data-kind:baseball">野球成績</button><button class="${dataManagerKind==='ability'?'on':''}" data-action="data-kind:ability">パフォーマンス測定</button><button class="${dataManagerKind==='inbody'?'on':''}" data-action="data-kind:inbody">InBody</button></div><div class="mode-tabs"><button class="${dataManagerMode==='input'?'on':''}" data-action="data-mode:input">入力・編集</button><button class="${dataManagerMode==='transfer'?'on':''}" data-action="data-mode:transfer">CSV入出力</button><button class="${dataManagerMode==='manage'?'on':''}" data-action="data-mode:manage">設定・バックアップ</button></div>${dataManagerMode==='input'?renderInput():dataManagerMode==='transfer'?renderCSVPanel():renderManage()}`;}
function renderCSVPanel(){const kind=dataManagerKind;return `<section class="card stack"><h3 class="section-title">${esc(prettyType(kind))}｜CSVファイル入出力</h3><p class="note">Excelで開けるUTF-8（BOM付き）CSVを出力します。CSVを取り込む前に、必ずJSONバックアップを保存してください。対象データは3種類のみです。</p><div class="row">${btn('csv-export','このデータをCSVで出力','btn primary')}${btn('csv-template','空のCSVテンプレート','btn')}</div><div class="field"><label for="csv-import-file">CSVを取り込む（列構成はテンプレートに合わせる）</label><input id="csv-import-file" type="file" accept=".csv,text/csv"></div><p class="note">記録IDで更新せず、新規データとして追加します。選手ID・日付などの重複を検査します。サンプルデータを含む試作環境専用です。</p><div class="row">${btn('export','全データをJSONでバックアップ','btn small')}</div></section>`;}
function csvColumns(kind){let common=['playerId','date'];if(kind==='baseball')return [...common,'category','opponent','gameType','tournament',...[...new Set(Object.values(BAT_FIELDS).flat().map(x=>x[0]))].map(v=>'v_'+v)];if(kind==='inbody')return [...common,...['height','weight','muscle','fatMass','fatRate','lean','water','rightArm','leftArm','trunk','rightLeg','leftLeg'].map(v=>'v_'+v)];return [...common,...state.metrics.map(m=>'v_'+m.id)];}
function csvEscape(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;}
function csvDownload(kind,template=false){const cols=csvColumns(kind),rows=template?[]:state.records.filter(r=>r.kind===kind).map(r=>cols.map(c=>{if(c==='playerId'||c==='date'||['category','opponent','gameType','tournament'].includes(c))return r[c]||'';return r.values?.[c.slice(2)]??'';}));const csv='\uFEFF'+[cols,...rows].map(row=>row.map(csvEscape).join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=`KYUTECH_${kind}_${template?'template':'data'}_${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);message(template?'テンプレートを出力しました':'CSVを出力しました');}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x!==''))rows.push(row);row=[];value='';}else value+=c;}if(quoted)throw Error('CSVの引用符が閉じられていません');row.push(value);if(row.some(x=>x!==''))rows.push(row);return rows;}
async function importCSV(file){if(!file)return;if(file.size>5*1024*1024)throw Error('CSVは5MB以下にしてください');const rows=parseCSV(await file.text());if(rows.length<2)throw Error('CSVにデータ行がありません');if(rows.length>3002)throw Error('一度に取り込めるのは3000行までです');const cols=csvColumns(dataManagerKind),header=rows[0];if(cols.length!==header.length||cols.some((v,i)=>v!==header[i]))throw Error('列名または列の順序がテンプレートと異なります');const incoming=[],existing=new Set(state.records.filter(r=>r.kind===dataManagerKind).map(r=>`${r.playerId}|${r.date}|${r.category||''}|${r.opponent||''}`));for(let i=1;i<rows.length;i++){const values=rows[i];if(values.length!==header.length)throw Error(`${i+1}行目の列数が違います`);const o=Object.fromEntries(header.map((k,j)=>[k,values[j]]));if(!state.players.some(p=>p.id===o.playerId))throw Error(`${i+1}行目：選手IDがありません`);if(!/^\d{4}-\d{2}-\d{2}$/.test(o.date)||Number.isNaN(Date.parse(o.date+'T00:00:00')))throw Error(`${i+1}行目：日付が不正です`);if(dataManagerKind==='baseball'&&(!['batting','pitching','fielding','running'].includes(o.category)||!o.opponent))throw Error(`${i+1}行目：野球成績の区分・対戦相手が不正です`);const k=`${o.playerId}|${o.date}|${o.category||''}|${o.opponent||''}`;if(existing.has(k))throw Error(`${i+1}行目：同日同区分の記録が既にあります（重複防止）`);existing.add(k);const nums={};for(const col of cols.filter(c=>c.startsWith('v_'))){if(o[col]==='')continue;const n=Number(o[col]);if(!Number.isFinite(n)||n<0)throw Error(`${i+1}行目：数値が不正です`);nums[col.slice(2)]=n;}if(!Object.keys(nums).length)throw Error(`${i+1}行目：数値がありません`);const at=new Date().toISOString();incoming.push({id:id(),playerId:o.playerId,date:o.date,kind:dataManagerKind,values:nums,category:o.category||undefined,opponent:o.opponent||undefined,gameType:o.gameType||undefined,tournament:o.tournament||undefined,createdAt:at,updatedAt:at,source:'csv'});}if(!confirm(`${incoming.length}件の${prettyType(dataManagerKind)}データを追加します。事前にJSONバックアップを取得しましたか？`))return;const before=state.records.slice();state.records.push(...incoming);if(!(await persist(`${incoming.length}件を取り込みました`)))state.records=before;render();}
function render(){
 const u=signedUser();if(!u){renderLogin();return;}
 activeRole=u.role;
 if(activeRole==='parent'||activeRole==='player')selected=effectivePlayer();
 const menu=activeRole==='staff'?STAFF_SCREENS:activeRole==='admin'?ADMIN_SCREENS:activeRole==='player'?PLAYER_SCREENS:PARENT_SCREENS;
 if(!menu.some(([k])=>k===screen))screen=menu[0][0];
 const pages=activeRole==='staff'?{guide:renderStaffGuide,practice:renderStaffPractice,history:renderDashboard,data:renderDataCenter,staffMessages:renderStaffMessages}:activeRole==='admin'?{home:renderAdminHome,longGoals:renderDirectorGoals,analysis:renderDirectorAnalysis,coaches:renderDirectorCoach,data:renderDataCenter,staffMessages:renderStaffMessages}:activeRole==='player'?{home:renderPlayerHomeV15,history:renderPersonalDashboard,goalPlan:renderPlayerGoalPlan,playerTraining:renderPlayerRecordV15}: {practice:renderParentPractice,history:renderPersonalDashboard,parentMessages:renderParentGuidance};
 const content=pages[screen]();
 const mobile=activeRole==='player'||activeRole==='parent';
 ROOT.innerHTML=`<div class="growth-shell ${mobile?'mobile-shell':'desktop-shell'} role-${activeRole}">
 <header class="growth-header"><div class="identity"><img src="./apple-touch-icon.png" alt=""><div><h1>KYUTECH GROWTH</h1><small>${mobile?'自分を知る。課題を知る。考える。成長する。':'選手育成・成長管理'}</small></div></div><span class="role">${esc(ROLE_NAMES[activeRole])}</span></header>
 <div class="growth-layout">${mobile?'':`<aside class="desktop-sidebar"><div class="sidebar-brand">${esc(ROLE_NAMES[activeRole])} ワークスペース</div><nav class="growth-nav" aria-label="メインメニュー">${menu.map(([k,v,icon])=>`<button class="${screen===k?'on':''}" data-screen="${k}">${navIcon(icon)}<span>${esc(v)}</span></button>`).join('')}</nav><div class="sidebar-bottom">${demoIdentity()}</div></aside>`}
 <div class="growth-main-wrap">${mobile?`<div class="mobile-user-row">${demoIdentity()}</div>`:''}<div id="notice" role="status" aria-live="polite" ${notice?'class="feedback'+(noticeError?' error':'')+'"':'hidden'}>${esc(notice)}</div><main class="growth-main">${content}</main><footer class="footer">KYUTECH GROWTH v1.5 UI試作｜端末内保存のみ。<b>本物の認証・クラウド共有・チーム間の権限分離は未実装です。実際の個人情報は入力しないでください。</b></footer></div>
 ${mobile?`<nav class="mobile-bottom-nav" aria-label="メインメニュー">${menu.map(([k,v,icon])=>`<button class="${screen===k?'on':''}" data-screen="${k}">${navIcon(icon)}<span>${esc(v)}</span></button>`).join('')}</nav>`:''}</div></div>`;
}
