function playerDemoLineChart(data,key,goal,unit,{height=218,compact=false}={}){
 const W=760,H=height,L=48,R=24,T=22,B=36;
 const all=data.map(x=>Number(x[key]));all.push(goal);
 let lo=Math.min(...all),hi=Math.max(...all),gap=(hi-lo)*.18||1;
 lo=Math.max(0,lo-gap);hi+=gap;
 if(hi<=lo)hi=lo+1;
 const dates=data.map(x=>dateMs(x.date));let dMin=Math.min(...dates),dMax=Math.max(...dates);if(dMin===dMax)dMax+=86400000;
 const px=d=>L+(dateMs(d)-dMin)/(dMax-dMin)*(W-L-R),py=v=>T+(hi-v)/(hi-lo)*(H-T-B);
 const lines=Array.from({length:4},(_,i)=>{let v=lo+(hi-lo)*i/3,y=py(v);return `<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#E8EDF2"/><text x="${L-7}" y="${y+4}" text-anchor="end" font-size="12" fill="#65748A">${readableNum(v)}</text>`}).join('');
 const p=data.map((x,i)=>`${i?'L':'M'}${px(x.date).toFixed(1)},${py(x[key]).toFixed(1)}`).join(' ');
 const points=data.map(x=>`<circle cx="${px(x.date)}" cy="${py(x[key])}" r="5.5" fill="#0F1B2E" stroke="white" stroke-width="2"><title>${esc(x.date)} ${esc(x.opponent)}: ${esc(x[key])}${esc(unit)}</title></circle>`).join('');
 const ticks=data.filter((x,i)=>i===0||i===data.length-1||(!compact&&i%2===0)).map(x=>`<text x="${px(x.date)}" y="${H-10}" text-anchor="middle" font-size="12" fill="#647084">${esc(x.date.slice(5).replace('-','/'))}</text>`).join('');
 return `<div class="development-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(key==='era'?'試合別防御率':key==='velocity'?'球速':'ストライク率')}の折れ線グラフ。目標を点線で表示" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet">${lines}<line x1="${L}" x2="${W-R}" y1="${py(goal)}" y2="${py(goal)}" stroke="#FF668E" stroke-width="2.6" stroke-dasharray="8 6"/><path d="${p}" fill="none" stroke="#0F1B2E" stroke-width="3.1" stroke-linecap="round" stroke-linejoin="round"/>${points}${ticks}<text x="${W-R}" y="${Math.max(14,py(goal)-8)}" text-anchor="end" fill="#C33A65" font-size="13" font-weight="bold">目標 ${readableNum(goal)}${esc(unit)}</text></svg></div>`;
}
function renderPlayerHomeCalendar(){
 const [y,m]=playerCalMonth.split('-').map(Number),first=new Date(y,m-1,1).getDay(),days=new Date(y,m,0).getDate(),training=playerTrainRecords();
 const countByDay={};for(const r of training)countByDay[r.date]=(countByDay[r.date]||0)+1;
 const cells=Array.from({length:first},()=>'<span class="calendar-cell blank" aria-hidden="true"></span>');
 for(let d=1;d<=days;d++){const date=playerCalMonth+'-'+String(d).padStart(2,'0'),done=!!countByDay[date];cells.push(`<button class="calendar-cell ${done?'done':''} ${date===playerCalDay?'selected':''} ${date===today()?'current':''}" data-action="cal-day:${date}" aria-label="${date}${done?' 自主練実施':''}" aria-pressed="${date===playerCalDay}"><span>${d}</span>${done?'<i class="calendar-mark" aria-hidden="true"></i>':''}</button>`)}
 const recent=training.filter(r=>r.date===playerCalDay);
 return `<div class="calendar-top"><button class="btn small" data-action="cal-month:-1" aria-label="前の月">‹</button><h3>${y}年${m}月</h3><button class="btn small" data-action="cal-month:1" aria-label="次の月">›</button></div><div class="calendar-grid">${['日','月','火','水','木','金','土'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${cells.join('')}</div><div class="home-calendar-footer"><span><i class="calendar-mark"></i> 実施日：${Object.keys(countByDay).filter(d=>d.startsWith(playerCalMonth)).length}日</span><span>${esc(playerCalDay.slice(5).replace('-','/'))}：${recent.length?recent.map(r=>esc(r.activityName||'トレーニング')).join('・'):'記録なし'}</span></div>`;
}
