 <section class="card development-panel dev-strike"><div class="dev-panel-heading"><div><span class="dev-eyebrow">SUB PERFORMANCE 02</span><h3>試合別ストライク率</h3></div><div class="dev-small-stat"><strong>${latest.strike}</strong><span>%</span></div></div>${playerDemoLineChart(data,'strike',strikeGoal,'%',{height:195,compact:true})}</section>
